// Extract status of all 3 software services
let hrOk = false, ragOk = false, n8nOk = false;

try {
  const hrData = $items('Check HR Portal (Port 8005)');
  hrOk = hrData && hrData.length > 0 && !!hrData[0].json;
} catch(e) { hrOk = false; }

try {
  const ragData = $items('Check RAG KMS (Port 8000)');
  ragOk = ragData && ragData.length > 0 && !!ragData[0].json;
} catch(e) { ragOk = false; }

try {
  const n8nData = $items('Check n8n Engine (Port 5678)');
  n8nOk = n8nData && n8nData.length > 0 && !!n8nData[0].json;
} catch(e) { n8nOk = false; }

const hrStatus = hrOk ? '🟢 UP (200 OK)' : '🔴 DOWN';
const ragStatus = ragOk ? '🟢 UP (200 OK)' : '🔴 DOWN';
const n8nStatus = n8nOk ? '🟢 UP (200 OK)' : '🔴 DOWN';

const isAllHealthy = hrOk && ragOk && n8nOk;
const statusSummary = isAllHealthy ? '🟢 ALL 3 SYSTEMS OPERATIONAL' : '⚠️ ALERT: ONE OR MORE SERVICES DOWN';

const emailHtml = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; border: 1px solid #e2e8f0; border-radius: 12px; overflow: hidden;">
  <div style="background-color: ${isAllHealthy ? '#0f766e' : '#b91c1c'}; color: white; padding: 20px; text-align: center;">
    <h2 style="margin: 0;">🖥️ RIS EC2 Daily System Health Report</h2>
    <p style="margin: 6px 0 0 0; font-size: 1.1rem; font-weight: bold;">${statusSummary}</p>
  </div>
  <div style="padding: 24px; background-color: #f8fafc;">
    <h3 style="color: #1e293b; border-bottom: 2px solid #cbd5e1; padding-bottom: 8px; margin-top: 0;">📡 Active Software Services</h3>
    <table style="width: 100%; border-collapse: collapse; font-size: 0.95rem;">
      <tr style="border-bottom: 1px solid #e2e8f0;"><td style="padding: 10px 0; font-weight: bold;">1. HR Career Portal (Port 8005):</td><td style="text-align: right; font-weight: bold;">${hrStatus}</td></tr>
      <tr style="border-bottom: 1px solid #e2e8f0;"><td style="padding: 10px 0; font-weight: bold;">2. KMS RAG System (Port 8000):</td><td style="text-align: right; font-weight: bold;">${ragStatus}</td></tr>
      <tr><td style="padding: 10px 0; font-weight: bold;">3. n8n Automation Engine (Port 5678):</td><td style="text-align: right; font-weight: bold;">${n8nStatus}</td></tr>
    </table>
  </div>
  <div style="background-color: #e2e8f0; text-align: center; padding: 12px; font-size: 0.85rem; color: #64748b;">
    Automated Daily System Monitoring • RIS Infrastructure Team
  </div>
</div>
`;

return [{
  json: {
    subject: `[System Health] ${statusSummary} - EC2 Server (${new Date().toLocaleDateString()})`,
    emailHtml,
    isAllHealthy
  }
}];
